"""Render the human-readable News Ontology from its Python data contract."""

from pathlib import Path

from . import news, primary

GENERATED_PATH = Path(__file__).resolve().parents[3] / "news-ontology.md"


def render_news_ontology() -> str:
    lines = [
        "<!-- Generated by `uv run python -m knowledge_map.ontology.render`; do not edit. -->",
        "# News Ontology", "",
        "The closed set of graph structures the news pipeline can produce. It is a subset",
        "of the primary ontology plus the declared shortcuts below.", "",
        "## Labels and properties", "",
        "| Label | Property names | Sub-labels |", "| --- | --- | --- |",
    ]
    for label in sorted(news.LABELS):
        properties = ", ".join(f"`{item}`" for item in sorted(news.PROPERTIES[label])) or "—"
        sub_labels = ", ".join(f"`{item}`" for item in sorted(news.SUB_LABELS.get(label, ()))) or "—"
        lines.append(f"| `{label}` | {properties} | {sub_labels} |")

    lines.extend(["", "## Relationships", "", "| Type | Sources | Targets |", "| --- | --- | --- |"])
    for relationship_type, shape in sorted(news.RELATIONSHIPS.items()):
        sources = " / ".join(f"`{item}`" for item in sorted(shape.source_labels))
        targets = " / ".join(f"`{item}`" for item in sorted(shape.target_labels))
        lines.append(f"| `{relationship_type}` | {sources} | {targets} |")

    lines.extend(["", "## Shortcuts", ""])
    for shortcut in news.SHORTCUTS:
        path = " → ".join(
            f"`{source}` -`{relationship}`→ `{target}`"
            for source, relationship, target in shortcut.path
        )
        lines.append(
            f"- {path} ⇒ `{shortcut.source_label}` -`{shortcut.relationship_type}`→ "
            f"`{shortcut.target_label}` (`skips`: `{shortcut.skips}`)"
        )

    shortcut_types = {shortcut.relationship_type for shortcut in news.SHORTCUTS}
    excluded_relationships = sorted(
        primary.RELATIONSHIPS.keys() - news.RELATIONSHIPS.keys() - shortcut_types
    )
    lines.extend(
        [
            "", "## Primary ontology concepts outside news scope", "",
            "Labels: "
            + ", ".join(f"`{label}`" for label in sorted(primary.LABELS - news.LABELS))
            + ".", "",
            "Relationships: "
            + ", ".join(f"`{item}`" for item in excluded_relationships)
            + ".",
        ]
    )

    lines.extend(["", "## Policy Areas", "", "| ID | Name |", "| --- | --- |"])
    lines.extend(f"| `{area.id}` | {area.name} |" for area in news.POLICY_AREAS)
    return "\n".join(lines) + "\n"


def main() -> None:
    GENERATED_PATH.write_text(render_news_ontology())


if __name__ == "__main__":
    main()
